import{_ as n,a8 as e,o as s,c as d,ah as i,K as r}from"./chunks/framework.BUAh2RRO.js";import"./chunks/theme.-p-ond56.js";const _=JSON.parse('{"title":"T5（Text-to-Text Transfer Transformer）","description":"","frontmatter":{"title":"T5（Text-to-Text Transfer Transformer）","abstract":"T5 迁移学习模型讲解，其将所有 NLP 任务统一为文本到文本格式，涵盖统一框架、架构设计、训练策略与主要结论。","created":"2026-07-10T00:00:00.000Z","tags":["NLP","预训练模型","Transformer"],"type":"概念解释","category":["🤖 AI大模型","NLP基础"]},"headers":[],"relativePath":"vault/Knowledge/AI/T5（Text-to-Text Transfer Transformer）.md","filePath":"vault/Knowledge/AI/T5（Text-to-Text Transfer Transformer）.md","lastUpdated":1790655645000}'),l={name:"vault/Knowledge/AI/T5（Text-to-Text Transfer Transformer）.md"};function T(h,t,c,m,f,x){const a=e("NolebaseGitContributors"),o=e("NolebaseGitChangelog");return s(),d("div",null,[t[0]||(t[0]=i('<h1 id="t5-text-to-text-transfer-transformer" tabindex="-1">T5（Text-to-Text Transfer Transformer） <a class="header-anchor" href="#t5-text-to-text-transfer-transformer" aria-label="Permalink to “T5（Text-to-Text Transfer Transformer）”">​</a></h1><p>T5 将所有 NLP 任务统一为 <strong>Text-to-Text</strong> 格式，输入和输出均为文本序列。</p><h2 id="统一框架" tabindex="-1">统一框架 <a class="header-anchor" href="#统一框架" aria-label="Permalink to “统一框架”">​</a></h2><table tabindex="0"><thead><tr><th>任务</th><th>输入格式</th><th>输出</th></tr></thead><tbody><tr><td>翻译</td><td>&quot;translate English to German: That is good.&quot;</td><td>&quot;Das ist gut.&quot;</td></tr><tr><td>分类</td><td>&quot;sst2 sentence: This movie is great.&quot;</td><td>&quot;positive&quot;</td></tr><tr><td>摘要</td><td>&quot;summarize: (长文本)&quot;</td><td>(摘要)</td></tr><tr><td>QA</td><td>&quot;question: (问题) context: (段落)&quot;</td><td>(答案)</td></tr></tbody></table><h2 id="架构" tabindex="-1">架构 <a class="header-anchor" href="#架构" aria-label="Permalink to “架构”">​</a></h2><p><strong>Encoder-Decoder</strong> 标准 Transformer：</p><ul><li>Encoder：双向注意力（类似 BERT）</li><li>Decoder：单向自回归注意力（类似 GPT）</li><li>使用 <strong>relative position bias</strong> 替代绝对位置编码</li></ul><h2 id="训练策略" tabindex="-1">训练策略 <a class="header-anchor" href="#训练策略" aria-label="Permalink to “训练策略”">​</a></h2><ul><li><strong>C4 数据集</strong>：从 Common Crawl 清洗出 750GB 高质量文本</li><li><strong>Span Corruption</strong>：随机遮蔽连续 token 片段，模型预测被遮蔽的片段序列</li><li>探索了模型缩放、预训练目标、训练时长等系统消融实验</li></ul><h2 id="主要结论" tabindex="-1">主要结论 <a class="header-anchor" href="#主要结论" aria-label="Permalink to “主要结论”">​</a></h2><p>T5 的系统性实验表明：Encoder-Decoder 架构在迁移学习中表现最优，span corruption 训练目标效果最好，更大的模型和数据量持续提升性能。</p>',11)),r(a),r(o)])}const g=n(l,[["render",T]]);export{_ as __pageData,g as default};
